# builds "DIODE 909 - User Manual.pdf" and "DIODE 909 - Update History.pdf" (headless Chrome)
import subprocess, os
os.chdir(os.path.dirname(os.path.abspath(__file__)))
VERSION = "1.1.0"
CSS = """<style>@page{size:A4;margin:18mm 16mm}body{font-family:Arial,sans-serif;color:#222;font-size:10.5pt;line-height:1.45}
h1{font-size:30pt;margin:0;font-style:italic;color:#1a1a1a}.sub{color:#e0601a;font-size:13pt;margin-bottom:16px}
h2{color:#c8361d;border-bottom:2px solid #f08a24;padding-bottom:3px;margin-top:20px}section{break-inside:avoid}
img{width:100%;border:1px solid #444;margin:6px 0}table{border-collapse:collapse;width:100%}td,th{border:1px solid #bbb;padding:4px 6px;vertical-align:top;text-align:left}th{background:#f6e3c9}
.stripe{height:5px;background:linear-gradient(90deg,#d62e1f 25%,#f57a1f 25% 50%,#fad542 50% 75%,#ede6cc 75%);margin:8px 0 18px}.warn{background:#fff3e0;border-left:4px solid #f08a24;padding:8px 10px}
</style>"""
def page(body): return "<html><head><meta charset=utf-8>" + CSS + "</head><body>" + body + "</body></html>"
man = """<h1>DIODE 909</h1><div class=sub>Rhythm Composer for Max for Live — User Manual · version """ + VERSION + """</div><div class=stripe></div>
<img src="bd.png">
<section><h2>Contents</h2><ol><li>Overview</li><li>System Requirements</li><li>Installation</li><li>macOS Security Warning</li><li>The Panel</li><li>Sound Controls</li><li>Programming Patterns</li><li>Accent</li><li>Flam</li><li>Swing</li><li>Hi-Hats</li><li>Patterns, Chains, Mute and Solo</li><li>MIDI</li><li>Push 3</li><li>Credits</li></ol></section>
<section><h2>1. Overview</h2><p>DIODE 909 is a TR-909 for Ableton Live. It joins an x0x step sequencer with the <b>DIODE 909 circuit engine</b>: the bass drum, snare, three toms, rim shot and hand clap are simulated from the original schematics at circuit level, and the hi-hats, crash and ride play the 909's own 6-bit sample data through the 909's counters, D/A converters, VCAs and filters — exactly as the hardware makes them. Everything is inside the device: there are no sample files to load.</p><p>DIODE 909 runs inside Live, works with Push 3, and stores its patterns with your Live Set.</p></section>
<section><h2>2. System Requirements</h2><table><tr><th>Item</th><th>Requirement</th></tr><tr><td>Ableton Live</td><td>Live 12 Suite (or Live 12 Standard with Max for Live)</td></tr><tr><td>macOS</td><td>macOS 12 Monterey or later, Apple Silicon or Intel</td></tr><tr><td>Windows</td><td>Windows 10 or 11, 64-bit</td></tr><tr><td>CPU</td><td>A circuit simulation is heavier than a sample player: a recent multi-core CPU (Apple M1 or better) is recommended. DIODE 909 spreads its voices over several cores, and silent voices rest. Set QUALITY to ECO for about a third less CPU.</td></tr><tr><td>Push</td><td>Compatible with Push 3 controlling Live</td></tr></table></section>
<section><h2>3. Installation</h2><p>Drop <b>DIODE 909.amxd</b> onto a MIDI track in Live, or save it to your User Library to find it in the browser. The device is self-contained: nothing else needs installing.</p></section>
<section><h2>4. macOS Security Warning</h2><div class=warn><p>DIODE 909 contains a compiled sound engine that is not notarised by Apple. The first time you load the device, macOS may block the engine with a message that it "cannot be opened because the developer cannot be verified" or that Apple "cannot check it for malicious software". If that happens:</p><ol><li>Click <b>Done</b> (or <b>OK</b>) on the message.</li><li>Open <b>System Settings → Privacy &amp; Security</b> (on macOS 12: System Preferences → Security &amp; Privacy → General).</li><li>Find the line about <b>diode909~</b> being blocked and click <b>Allow Anyway</b> / <b>Open Anyway</b>.</li><li>Remove DIODE 909 from the track and load it again; confirm with <b>Open</b> if macOS asks once more.</li></ol><p>You only need to do this once.</p></div></section>
<section><h2>5. The Panel</h2><p>The panel follows the TR-909's front panel.</p><p><b>Top:</b> every sound control at once, grouped under the navy instrument bars — TOTAL ACCENT, BASS DRUM, SNARE DRUM, LOW TOM, MID TOM, HI TOM, RIM SHOT / HAND CLAP, HI HAT and CYMBAL. Each instrument has a small LED in its navy bar for mute and solo. On the right: the DIODE 909 logo (click it to open the store), the LAST STEP, CHANNEL and NOTE displays, and the master VOLUME knob.</p><p><b>Bottom:</b> WRITE, CLEAR, COPY and PASTE; the 16 step keys with their LEDs, grouped in fours with navy brackets, and the downbeats 1, 5, 9 and 13 marked in navy to make 4/4 beats easy to program; the instrument strip under the keys; the 16 pattern keys in two rows (red LED: playing; orange frame: being edited; orange tag: place in the chain).</p><p><b>Selecting an instrument:</b> click its name on the strip under the keys (on the shared strips click the left or right name: RIM SHOT · CLAP, CLOSED · OPEN, CRASH · RIDE), click its name in a navy bar above the knobs, or click its name above the M/S boxes. The selected instrument is shown in orange; the step keys show its pattern. Click TOTAL ACCENT to edit accents.</p><p><b>Mute and solo:</b> click an instrument's LED in its navy bar to mute it (the LED lights red). Alt/Option-click to solo it (the LED lights amber); Cmd/Ctrl-click solos only that instrument. On the shared bars the left LED is the left instrument and the right LED the right one (HI HAT: closed hat left, open hat right).</p></section>
<section><h2>6. Sound Controls</h2><p>Drag a knob up or down to turn it; Shift-drag for fine moves; double-click to return it to its factory position. While you turn a knob its value (0–10, or milliseconds for FLAM) appears under it. Every control is a Live parameter: automate it or map it.</p>
<table><tr><th>Group</th><th>Controls</th></tr><tr><td>TOTAL ACCENT</td><td>ACCENT · FLAM time · SWING · QUALITY (HQ / ECO switch)</td></tr><tr><td>BASS DRUM</td><td>TUNE · LEVEL · ATTACK · DECAY</td></tr><tr><td>SNARE DRUM</td><td>TUNE · LEVEL · TONE · SNAPPY</td></tr><tr><td>LOW / MID / HI TOM</td><td>TUNE · LEVEL · DECAY</td></tr><tr><td>RIM SHOT · HAND CLAP</td><td>LEVEL · LEVEL</td></tr><tr><td>HI HAT</td><td>LEVEL (both hats) · CH DECAY · OH DECAY</td></tr><tr><td>CYMBAL</td><td>CR LEVEL · RD LEVEL · CR TUNE · RD TUNE</td></tr><tr><td>VOLUME</td><td>Master level of the whole device</td></tr></table><img src="oh.png"><p>Above: the open hat selected, the low tom muted (red LED in its bar) and a chain of four patterns.</p></section>
<section><h3 style="color:#c8361d;margin:14px 0 4px">Quality: HQ and ECO</h3><p>The QUALITY switch (TOTAL ACCENT group) sets how DIODE 909 runs its circuits. <b>HQ</b> (factory setting) runs them at twice the sample rate for the cleanest highs. <b>ECO</b> runs them at the sample rate itself: about a third less CPU, with a slightly rougher top end. Click the switch to change it; the sound stops for a moment while the circuits restart. QUALITY is saved with your Live Set and can be automated, though switching while playing is not recommended.</p></section>
<section><h2>7. Programming Patterns</h2><p>Select a track, then click step keys to turn steps on or off (drag across keys to paint). The LED above a key shows the step. LAST STEP (drag) sets the pattern length, 1–16 steps. CLEAR empties the pattern (Shift-click: only the selected track). COPY and PASTE copy a whole pattern. With WRITE on and Live playing, MIDI notes you play are recorded into the playing pattern (velocity 120 or more records an accent).</p></section>
<section><h2>8. Accent</h2><p>Click TOTAL ACCENT to place accents: accented steps show their step number on an orange tab on every track. Like the 909, an accent drives the voice's accent circuit, not only its volume: the analog drums hit harder and brighter, the hats and cymbals play louder sample levels. The ACCENT knob sets how strong accented steps are.</p><img src="ac.png"><p>Above: the accent track selected, with the FLAM knob being turned (its value shows under it).</p></section>
<section><h2>9. Flam</h2><p><b>Alt/Option-click</b> a step key to make that step a flam: its LED turns <b style="color:#2a7bff">blue</b>. Alt-click it again to make it a normal step. A flam plays a quiet grace note and then the main hit a moment later. The FLAM knob (AC track) sets that time, 5 to 40 ms (factory 19 ms). The main hit keeps the step's accent.</p></section>
<section><h2>10. Swing</h2><p>The SWING knob (AC track) delays every second 16th step — steps 2, 4, 6 … — for a shuffled groove. At 0 the steps are straight (50 %); at 10 the delayed steps land at 75 % of the 8th note. Swing follows Live's tempo and applies to every track, accents and flams included.</p></section>
<section><h2>11. Hi-Hats</h2><p>As on the 909, the closed and open hat are one circuit: a closed hat cuts an open hat that is still ringing. The two tracks share the hi-hat LEVEL knob; each has its own DECAY.</p></section>
<section><h2>12. Patterns, Chains, Mute and Solo</h2><p>Click a pattern button to select it; while Live plays, the new pattern starts when the current one ends (it blinks while waiting). Shift-click pattern buttons to build a chain of up to 32 patterns played in order; click a pattern without Shift to clear the chain. Mute and solo instruments with the LEDs in their navy bars (see The Panel). The playhead follows Live's transport, sample-accurate.</p></section>
<section><h2>13. MIDI</h2><table><tr><th>Sound</th><th>Note</th><th>Sound</th><th>Note</th></tr><tr><td>BD</td><td>C1 36 (also B0 35)</td><td>CP</td><td>D#1 39</td></tr><tr><td>SD</td><td>D1 38 (also E1 40)</td><td>CH</td><td>F#1 42 (also G#1 44)</td></tr><tr><td>LT</td><td>G1 43 (also F1 41)</td><td>OH</td><td>A#1 46</td></tr><tr><td>MT</td><td>B1 47 (also A1 45)</td><td>CR</td><td>C#2 49</td></tr><tr><td>HT</td><td>D2 50 (also C2 48)</td><td>RD</td><td>D#2 51</td></tr><tr><td>RS</td><td>C#1 37</td><td colspan=2>Velocity 100 or more plays accented.</td></tr></table>
<p>On the edit channel (CHANNEL display, default 16): notes 36–51 toggle steps 1–16, notes 52–63 select tracks AC to RD, notes 72–87 select patterns 1–16.</p></section>
<section><h2>14. Push 3</h2><p>With DIODE 909 selected, Push 3 shows its sound controls in four banks: <b>Main</b> (Accent, Flam, Swing, Volume, RS and CP level, HH level, CH decay), <b>BD SD</b>, <b>Toms</b> and <b>Cymbals</b> (HT decay, OH decay, crash and ride level and tune, QUALITY). Play the drums from Push's pads in Drum mode with the notes above.</p></section>
<section><h2>15. Credits</h2><p>DIODE 909 by Transistor Labs (Ticco Ross). TR-909 is a trademark of Roland Corporation, which is not associated with this product.</p><p>Contact: ticcoross@gmail.com · Store: https://ticcoross.gumroad.com/</p></section>"""
hist = """<h1>DIODE 909</h1><div class=sub>Max for Live — Update History</div><div class=stripe></div>
<section><h2>1.1.0</h2><ul><li>QUALITY switch: HQ (factory) or ECO, about a third less CPU.</li><li>Lower CPU in both modes: voices rest sooner once their sound has died away.</li><li>4/4 guide on the step keys (downbeats 1, 5, 9, 13 marked, keys grouped in fours).</li><li>Mute and solo as LEDs in the instrument bars.</li><li>Pattern slots as 909 keys, two rows of eight; displays beside the logo.</li><li>Knobs show their position at every value.</li></ul></section>
<section><h2>1.0.0</h2><ul><li>First release.</li><li>The DIODE 909 circuit engine inside the x0x sequencer panel: circuit-level bass drum, snare, toms, rim shot and clap; hi-hats, crash and ride through the 909's sample playback circuits, built in.</li><li>All sound controls of the 909 front panel; master volume.</li><li>Accent, flam (Alt/Option-click, blue LED, 5–40 ms) and swing.</li><li>16 patterns, chains, mute/solo, MIDI in and WRITE recording.</li><li>TR-909 style panel: every sound control visible at once.</li><li>Push 3 parameter banks.</li></ul></section>"""
for name, b in [("DIODE 909 - User Manual", man), ("DIODE 909 - Update History", hist)]:
    open("_t.html", "w").write(page(b))
    subprocess.run(["google-chrome", "--headless", "--no-sandbox", "--disable-gpu", "--no-pdf-header-footer",
                    "--print-to-pdf=" + name + ".pdf", "_t.html"], check=True, capture_output=True)
os.remove("_t.html")
print("ok")
